use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (c: Vec<f32>)
    ensures
        c@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> c@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> c@[a@.len() + j] == b@[j],
{
    let mut c: Vec<f32> = Vec::new();

    // Push all elements of a
    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            c@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> c@[k] == a@[k],
        decreases a.len() - i,
    {
        c.push(a[i]);
        i += 1;
    }

    // Push all elements of b
    let a_len: usize = a.len();
    let mut j: usize = 0;
    while j < b.len()
        invariant
            a_len == a.len(),
            0 <= j <= b.len(),
            c@.len() == a_len as int + j as int,
            // a-part preserved
            forall|k: int| 0 <= k < a_len as int ==> c@[k] == a@[k],
            // b-part so far
            forall|k: int| 0 <= k < j as int ==> c@[a_len as int + k] == b@[k],
        decreases b.len() - j,
    {
        c.push(b[j]);
        j += 1;
    }

    c
}

} // verus!

